<?php requireUser(true); $tab=(string)($_GET['tab']??'dashboard'); ?>
<h1>Quản trị cửa hàng</h1><nav class="tabs"><?php foreach(['dashboard'=>'Tổng quan','settings'=>'Cấu hình website','quotes'=>'Yêu cầu báo giá','products'=>'Sản phẩm','categories'=>'Danh mục','orders'=>'Đơn hàng','customers'=>'Khách hàng','coupons'=>'Mã giảm giá'] as $key=>$label): ?><a class="button secondary" href="/?page=admin&tab=<?= $key ?>"><?= $label ?></a><?php endforeach ?></nav>
<?php switch($tab): case 'dashboard': ?>
<div class="grid stats"><?php foreach(['Doanh thu đã hoàn tất'=>money((int)query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status='completed' AND paid=1")->fetchColumn()),'Tổng đơn hàng'=>query('SELECT COUNT(*) FROM orders')->fetchColumn(),'Đơn chờ xác nhận'=>query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn(),'Sản phẩm sắp hết (≤ 5)'=>query('SELECT COUNT(*) FROM products WHERE stock<=5 AND active=1')->fetchColumn()] as $label=>$value): ?><div class="panel"><small><?= $label ?></small><h2><?= $value ?></h2></div><?php endforeach ?></div><h2>Đơn hàng gần đây</h2><?php $orders=query('SELECT * FROM orders ORDER BY id DESC LIMIT 20')->fetchAll(); require ROOT.'/app/order-table.php'; break;
case 'settings': ?><section class="panel narrow"><h2>Thương hiệu & hình ảnh</h2><p>Nhập ảnh gốc đã được phép sử dụng. URL ảnh phải dùng HTTPS.</p><?php startForm('site_settings'); foreach(['brand'=>'Tên thương hiệu','phone'=>'Điện thoại','address'=>'Địa chỉ','hero_image'=>'Ảnh đầu trang','portrait_image'=>'Chân dung nghệ nhân','work_image_1'=>'Ảnh tác phẩm / chế tác 1','work_image_2'=>'Ảnh tác phẩm / chế tác 2','work_image_3'=>'Ảnh tác phẩm / chế tác 3'] as $key=>$label) input($label,$key,str_contains($key,'image')?'url':'text',setting($key,$key==='brand'?'Nghệ nhân Văn Nho':''),$key==='brand'); ?><button>Lưu cấu hình</button></form></section><?php break;
case 'quotes': ?><section class="panel"><h2>Yêu cầu tư vấn & báo giá</h2><?php $requests=query('SELECT q.*,p.name product_name FROM quote_requests q LEFT JOIN products p ON p.id=q.product_id ORDER BY q.id DESC LIMIT 200')->fetchAll(); if(!$requests) echo '<p>Chưa có yêu cầu.</p>'; foreach($requests as $q): ?><article class="coupon"><h3>#<?= $q['id'] ?> · <?= e($q['name']) ?></h3><p><?= e($q['phone']) ?> · <?= e($q['location']) ?><br>Mẫu: <?= e($q['product_name']?:'Thiết kế riêng') ?><br><?= e($q['material']) ?> · <?= e($q['dimensions']) ?></p><p><?= nl2br(e($q['notes'])) ?></p><?php startForm('quote_status'); ?><input type="hidden" name="id" value="<?= $q['id'] ?>"><select name="status"><?php foreach(['new'=>'Mới','contacted'=>'Đã liên hệ','quoted'=>'Đã báo giá','closed'=>'Đã đóng'] as $key=>$label): ?><option value="<?= $key ?>" <?= $key===$q['status']?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button>Cập nhật</button></form></article><?php endforeach ?></section><?php break;
case 'products': $edit=query('SELECT * FROM products WHERE id=?',[(int)($_GET['edit']??0)])->fetch()?:['id'=>0,'name'=>'','description'=>'','price'=>0,'stock'=>0,'category_id'=>0,'image'=>'','active'=>1]; ?>
<div class="detail"><section class="panel"><h2><?= $edit['id']?'Sửa sản phẩm':'Thêm sản phẩm' ?></h2><?php startForm('product'); ?><input type="hidden" name="id" value="<?= $edit['id'] ?>"><?php input('Tên sản phẩm','name','text',$edit['name']); ?><label>Danh mục<select name="category_id" required><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $edit['category_id']===$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></label><label>Mô tả<textarea name="description" required><?= e($edit['description']) ?></textarea></label><?php input('Giá (VND)','price','number',$edit['price']); input('Tồn kho','stock','number',$edit['stock']); input('URL ảnh HTTPS','image','url',$edit['image'],false); ?><label><input type="checkbox" name="active" <?= $edit['active']?'checked':'' ?>> Hiển thị sản phẩm</label><button>Lưu sản phẩm</button></form></section><section class="panel table-wrap"><table><tr><th>Tên</th><th>Giá / Tồn</th><th>Hiển thị</th></tr><?php foreach(query('SELECT * FROM products ORDER BY id DESC')->fetchAll() as $p): ?><tr><td><a href="/?page=admin&tab=products&edit=<?= $p['id'] ?>"><?= e($p['name']) ?></a></td><td><?= money((int)$p['price']) ?> / <?= $p['stock'] ?></td><td><?= $p['active']?'Có':'Ẩn' ?></td></tr><?php endforeach ?></table></section></div>
<?php break; case 'categories': ?><section class="panel narrow"><h2>Danh mục</h2><?php foreach($categories as $c): ?><p><?= e($c['name']) ?></p><?php endforeach; startForm('category'); input('Tên danh mục mới','name'); ?><button>Thêm danh mục</button></form></section><?php break;
case 'orders': ?><form class="filters"><input type="hidden" name="page" value="admin"><input type="hidden" name="tab" value="orders"><select name="status"><option value="">Tất cả trạng thái</option><?php foreach(STATUSES as $key=>$label): ?><option value="<?= $key ?>" <?= ($_GET['status']??'')===$key?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button>Lọc</button></form><?php $filter=(string)($_GET['status']??''); $orders=$filter!==''?query('SELECT * FROM orders WHERE status=? ORDER BY id DESC LIMIT 200',[$filter])->fetchAll():query('SELECT * FROM orders ORDER BY id DESC LIMIT 200')->fetchAll(); require ROOT.'/app/order-table.php'; break;
case 'customers': ?><section class="panel table-wrap"><table><tr><th>Họ tên</th><th>Email</th><th>Ngày đăng ký</th><th>Số đơn</th></tr><?php foreach(query("SELECT u.*, (SELECT COUNT(*) FROM orders o WHERE o.user_id=u.id) order_count FROM users u WHERE role='customer' ORDER BY id DESC LIMIT 200")->fetchAll() as $c): ?><tr><td><?= e($c['name']) ?></td><td><?= e($c['email']) ?></td><td><?= e($c['created_at']) ?></td><td><?= $c['order_count'] ?></td></tr><?php endforeach ?></table></section><?php break;
case 'coupons': ?><div class="detail"><section class="panel"><h2>Thêm mã giảm giá</h2><?php startForm('coupon'); input('Mã (chữ, số, _ hoặc -)','code'); input('Phần trăm giảm (1–100)','percent','number',10); input('Giá trị đơn tối thiểu','min_total','number',0); input('Hết hạn','expires_at','date','',false); ?><button>Tạo mã</button></form></section><section class="panel"><h2>Danh sách mã</h2><?php foreach(query('SELECT * FROM coupons ORDER BY id DESC')->fetchAll() as $c): ?><article class="coupon"><h3><?= e($c['code']) ?> · <?= $c['percent'] ?>%</h3><p>Đơn từ <?= money((int)$c['min_total']) ?> · <?= e($c['expires_at']?:'Không hết hạn') ?></p><?php startForm('coupon_toggle'); ?><input type="hidden" name="id" value="<?= $c['id'] ?>"><button class="secondary"><?= $c['active']?'Tắt mã':'Bật mã' ?></button></form></article><?php endforeach ?></section></div><?php break; default: http_response_code(404); echo '<p>Mục quản trị không tồn tại.</p>'; endswitch ?>
